evidence.command:
rm -rf /tmp/p39v/boxsrc && mkdir -p /tmp/p39v/boxsrc/out
cp /tmp/p39head/src/test/modules/split/shapes.h.ct /tmp/p39head/src/test/modules/split/impl_dog.h.ct /tmp/p39v/boxsrc/
cat > /tmp/p39v/boxsrc/main.ct <<'EOF'
import shapes;
import impl_dog;

int main(void)
{
    Dog d;
    d.n = 3;
    Speak s = d;
    s.hi();
    return 0;
}
EOF
cd /tmp/p39head/src && /tmp/p39head/ct build --emit-c --outdir /tmp/p39v/boxsrc/out /tmp/p39v/boxsrc/main.ct
cd /tmp/p39v/boxsrc/out && for c in *.c; do cc -std=c99 -I. -c "$c" -o "${c%.c}.o"; done
ZERO_AR_DATE=1 ar rcs /tmp/p39v/libbox.a *.o
echo '--- ar t'; ar t /tmp/p39v/libbox.a
echo '--- nm -g --defined-only'; nm -g --defined-only /tmp/p39v/libbox.a

rm -rf /tmp/p39v/misuse && mkdir -p /tmp/p39v/misuse/out && cd /tmp/p39v/misuse
cp /tmp/p39head/src/test/modules/split/shapes.h.ct /tmp/p39head/src/test/modules/split/impl_dog.h.ct .
cat > main.ct <<'EOF'
import shapes;
import impl_dog;
int main(void) { Dog d; d.n = 3; Speak s = d; s.hi(); return 0; }
EOF
/tmp/p39head/ct build --emit-c --outdir out main.ct
cd out && for c in shapes.c impl_dog.c main.c; do cc -std=c99 -I. -c "$c" -o "${c%.c}.o"; done
cd ..
cc -std=c99 -I out -c out/shapes.c -o shapes.o
cc -std=c99 -I out -c out/impl_dog.c -o impl_dog.o
ZERO_AR_DATE=1 ar rcs libimpl.a shapes.o impl_dog.o
cat > consumer.c <<'EOF'
#include <stdio.h>
struct Dog { int n; };
struct Speak_vtbl { void (*hi)(void *); };
extern struct Speak_vtbl Dog_Speak_vtable;   /* NOT in any .abi.h */
int main(void) {
    struct Dog d = { 42 };
    Dog_Speak_vtable.hi(&d);
    return 0;
}
EOF
cc -std=c99 consumer.c libimpl.a -o misuse; echo "link rc=$?"
./misuse; echo "run rc=$?"
cc -std=c99 -fvisibility=hidden -I out -c out/impl_dog.c -o impl_dog.hid.o
echo '--- hidden: nm -g --defined-only impl_dog.hid.o'; nm -g --defined-only impl_dog.hid.o
ZERO_AR_DATE=1 ar rcs libhid.a shapes.o impl_dog.hid.o
cc -std=c99 consumer.c libhid.a -o misuse_hid; echo "hidden-misuse link rc=$?"
./misuse_hid; echo "run rc=$?"

rm -rf /tmp/p39v/strmisuse && mkdir -p /tmp/p39v/strmisuse/out && cd /tmp/p39v/strmisuse
cd /tmp/p39head/src && /tmp/p39head/ct build --emit-c -I lib lib/std/Str.h.ct --outdir /tmp/p39v/strmisuse/out --cc true >/dev/null
cd /tmp/p39v/strmisuse && cc -std=c99 -I out -c out/Str.c -o Str.o
ZERO_AR_DATE=1 ar rcs libstr.a Str.o
cat > cons.c <<'EOF'
#include <stdio.h>
/* NOT from any .abi.h: hand-mirrored internal Str layout + a non-ABI std symbol */
struct Str { char *data; int len; };
int str_len(struct Str);
int main(void) {
    struct Str s = { (char *)"abcd", 4 };
    printf("str_len=%d\n", str_len(s));
    return 0;
}
EOF
cc -std=c99 cons.c libstr.a -o strmisuse; echo "link rc=$?"
./strmisuse; echo "run rc=$?"

rm -rf /tmp/p39v/interpose && mkdir -p /tmp/p39v/interpose/out && cd /tmp/p39v/interpose
cat > helper.h.ct <<'EOF'
pub int helper(const char *s) { int n = 0; while (s[n]) n++; return n; }
EOF
cat > api.h.ct <<'EOF'
import helper;
pub int api(void) { return helper("abc"); }
EOF
/tmp/p39head/ct build --emit-c -I . api.h.ct --outdir out --cc true
for c in out/*.c; do cc -std=c99 -I out -c "$c" -o "${c%.c}.o"; done
echo '--- nm -g --defined-only'; nm -g --defined-only out/*.o
ZERO_AR_DATE=1 ar rcs libapi2.a out/api.o out/helper.o
cat > cons_ok.c <<'EOF'
#include <stdio.h>
int api(void);
int main(void) { printf("api=%d\n", api()); return 0; }
EOF
cat > cons_i.c <<'EOF'
#include <stdio.h>
int helper(const char *s) { (void)s; return 999; }   /* innocent-looking name */
int api(void);
int main(void) { printf("api=%d\n", api()); return 0; }
EOF
cc -std=c99 cons_ok.c libapi2.a -o ok; echo "ok link rc=$?"; ./ok; echo "run rc=$?"
cc -std=c99 cons_i.c libapi2.a -o interposed; echo "interposed link rc=$?"; ./interposed; echo "run rc=$?"
echo '--- archive nm unchanged'; nm -g --defined-only libapi2.a

rm -rf /tmp/p39v/mergebox && mkdir -p /tmp/p39v/mergebox/out && cd /tmp/p39v/mergebox
cp /tmp/p39head/src/test/modules/split/shapes.h.ct /tmp/p39head/src/test/modules/split/impl_dog.h.ct .
cat > box.h.ct <<'EOF'
import shapes;
import impl_dog;

pub void via_vtable(void)
{
    Dog d = *dog_get();
    Speak s = d;
    s.hi();
}
EOF
/tmp/p39head/ct build --emit-c -I . box.h.ct --outdir out --cc true
cd out && for c in *.c; do cc -std=c99 -I. -c "$c" -o "${c%.c}.o"; done
printf '_via_vtable\n_dog_get\n' > exp_box.txt
ld -r -exported_symbols_list exp_box.txt shapes.o impl_dog.o box.o -o merged.o; echo "merge rc=$?"
echo '--- nm -g merged'; nm -g --defined-only merged.o
echo '--- nm merged | grep -i dog'; nm merged.o | grep -i dog
echo '--- nm -u merged'; nm -u merged.o
ZERO_AR_DATE=1 ar rcs libmerged2.a merged.o
echo '--- ar t'; ar t libmerged2.a
cd .. && cat > cons.c <<'EOF'
void via_vtable(void);
int main(void) { via_vtable(); return 0; }
EOF
cc -std=c99 cons.c out/libmerged2.a -o mergedbin; echo "link rc=$?"; ./mergedbin; echo "run rc=$?"

rm -rf /tmp/p39v/merge3 && mkdir /tmp/p39v/merge3 && cd /tmp/p39v/merge3
cat > greetlib.ct <<'EOF'
#include <stdio.h>

pub trait Greeter {
    void greet();
}

pub struct Person {
    char *name;
} use Greeter;

impl Greeter for Person {
    void greet() { printf("hi %s\n", self->name); }
}

static Person ps[2];

pub void run_lib(void)
{
    ps[0].name = "A";
    ps[1].name = "B";
    ps[0].greet();
    ps[1].greet();
}
EOF
/tmp/p39head/ct greetlib.ct -o greetlib.c; echo "emit rc=$?"
grep -n "__ct_init" greetlib.c
cc -std=c99 -c greetlib.c -o greetlib.o
echo '--- nm -g unit'; nm -g --defined-only greetlib.o
echo '--- nm -m unit | init'; nm -m greetlib.o | grep -Ei 'init|vtable'
printf '_run_lib\n' > exp.txt
ld -r -exported_symbols_list exp.txt -o merged.o greetlib.o; echo "ld -r rc=$?"
echo '--- nm -g merged'; nm -g --defined-only merged.o
echo '--- nm -m merged init'; nm -m merged.o | grep -Ei 'init|run_lib|vtable'
ZERO_AR_DATE=1 ar rcs libmerged.a merged.o
echo '--- ar t'; ar t libmerged.a
cat > cons.c <<'EOF'
void run_lib(void);
int main(void) { run_lib(); return 0; }
EOF
cc -std=c99 cons.c libmerged.a -o mergbin; echo "consumer link rc=$?"
./mergbin; echo "run rc=$?"

rm -rf /tmp/p39v/merge4 && mkdir /tmp/p39v/merge4 && cd /tmp/p39v/merge4
