echo '--- nm -g unit'; nm -g --defined-only greetlib.o
printf '_run_lib\n' > exp.txt
ld -r -exported_symbols_list exp.txt -o merged.o greetlib.o; echo "ld rc=$?"
echo '--- nm -g merged'; nm -g --defined-only merged.o
echo '--- nm -m merged ps'; nm -m merged.o | grep -E '_ps$|common'
ZERO_AR_DATE=1 ar rcs libmerged.a merged.o; ar t libmerged.a
cat > cons.c <<'EOF'
void run_lib(void);
