cc -std=c99 cons.c libmerged.a -o mergbin; echo "link rc=$?"; ./mergbin; echo "run rc=$?"

rm -rf /tmp/p39v/perunit && mkdir -p /tmp/p39v/perunit/out && cd /tmp/p39v/perunit
cp /tmp/p39head/src/test/modules/split/shapes.h.ct /tmp/p39head/src/test/modules/split/impl_dog.h.ct .
cat > box.h.ct <<'EOF'
