EOF
/tmp/p39head/ct build --emit-c -I . box.h.ct --outdir out --cc true
for c in out/*.c; do cc -std=c99 -I out -c "$c" -o "${c%.c}.o"; done
echo '--- nm -g --defined-only per-unit objects'; nm -g --defined-only out/*.o
echo '--- nm -u box.o'; nm -u out/box.o
